<?php
// Instalação de uso único. Exclua este arquivo após concluir.
require __DIR__.'/app/core.php';
$done=__DIR__.'/app/installed.lock';if(file_exists($done)){http_response_code(403);exit('Instalação já concluída. Remova instalar.php do servidor.');}
$error='';$success=false;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$pass=(string)($_POST['pass']??'');if(strlen($name)<2||strlen($name)>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<12){$error='Informe nome, e-mail válido e senha de no mínimo 12 caracteres.';}else{
 try{$q=db()->query("SHOW TABLES LIKE 'users'");if(!$q->fetch())throw new RuntimeException('Importe database.sql primeiro pelo phpMyAdmin.');$count=(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn();if($count>0)throw new RuntimeException('Já existe administrador cadastrado.');$s=db()->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);if(file_put_contents($done,'installed')===false)throw new RuntimeException('Permissão insuficiente para criar app/installed.lock.');$success=true;
 }catch(Throwable $e){error_log($e->getMessage());$error='Falha na instalação. Confirme o banco e as permissões; verifique os logs do PHP.';}}
}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instalação MK3</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="login"><img src="assets/logo-mk3-oficial.png" alt="MK3" width="140"><h1>Instalação da MK3</h1><p>Importe <code>database.sql</code> no phpMyAdmin antes de continuar.</p><?php if($error):?><div class="alert"><?=h($error)?></div><?php endif;?><?php if($success):?><div class="alert ok">Administrador criado! <strong>Apague instalar.php agora</strong> e entre em <a href="admin/login.php">Administração</a>.</div><?php else:?><form method="post"><?=token_field()?><label>Nome<input name="name" required maxlength="120"></label><label>E-mail<input type="email" name="email" required></label><label>Senha forte (mínimo 12 caracteres)<input type="password" name="pass" required minlength="12"></label><p><button class="button red">CRIAR ADMINISTRADOR</button></p></form><?php endif;?></div></body></html>
